    function loadSaved(){try{var raw=localStorage.getItem('codename-sudoku-v1');if(!raw)return false;var saved=JSON.parse(raw);if(!saved||!levels[saved.level]||!Array.isArray(saved.values)||saved.values.length!==81||!Array.isArray(saved.solution)||saved.solution.length!==81)return false;game.level=saved.level;game.profileCategory=['classic','battle','friend'].includes(saved.profileCategory)?saved.profileCategory:'classic';game.solution=saved.solution;game.puzzle=saved.puzzle;game.values=saved.values;game.notes=Array.isArray(saved.notes)&&saved.notes.length===81?saved.notes.map(function(x){return Array.isArray(x)?x:[]}):Array.from({length:81},function(){return[]});game.mistakes=Math.min(3,Math.max(0,saved.mistakes|0));game.hints=Math.min(3,Math.max(0,saved.hints|0));game.seconds=Math.max(0,saved.seconds|0);game.undo=[];game.selected=-1;game.paused=false;game.finished=Boolean(saved.finished);return true}catch(e){return false}}
